import {whiteboardFixture} from './whiteboard';import type {ResearchCase} from '../../src/domain/research-case';
export function networkFixture(){const d=whiteboardFixture(),base=structuredClone(d.versions[0]),mapping=structuredClone(d.mappings[0]),review=structuredClone(d.reviews[0]),identity=structuredClone(d.identities[0]);base.payload.experiment.conditions[0].raw_value_text='SYNTHETIC 80 degC';base.payload.experiment.conditions[0].raw_unit='degC';for(const a of d.attestations)a.created_at='2026-10-02T00:00:00Z';d.versions=[];d.identities=[];d.mappings=[];d.reviews=[];const compounds=['A glucose','B intermediate','C product','D branch','A glucose','F coproduct'].map((name,i)=>({...base.payload.compounds[0],id:`90000000-0000-4000-8000-00000000000${i+1}`,name,node_type:i===4?'polymer':i===1?'intermediate':'discrete_molecule',structure_context:i===4?'bound':'free'})) as ResearchCase['compounds'];
 const reactions=[{name:'R1 A → B',from:[0],to:[1]},{name:'R2 B → C',from:[1],to:[2]},{name:'R3 B → D',from:[1],to:[3]},{name:'R4 A + cellulose → B + F',from:[0,4],to:[1,5]},{name:'R5 C → B (reverse)',from:[2],to:[1]}];
 reactions.forEach((r,i)=>{const v=structuredClone(base);v.id='network-version-'+i;v.case_id='network-case-'+i;v.payload.compounds=compounds.filter((_,j)=>[...r.from,...r.to].includes(j));v.payload.reaction.participants=[...r.from.map(j=>({compound_id:compounds[j].id,role:'reactant' as const,coefficient:1,primary_for_display:true})),...r.to.map(j=>({compound_id:compounds[j].id,role:'product' as const,coefficient:j===5?2:1,primary_for_display:true}))];v.payload.claim.proposition='SYNTHETIC '+r.name;v.payload.experiment.original_experiment_id='SYNTHETIC network '+i;v.payload.experiment.independence_group_id='SYNTHETIC network '+i;d.versions.push(v);d.identities.push({...identity,id:'network-identity-'+i,label:r.name,definition:structuredClone(v.payload),seed_version_id:v.id});d.mappings.push({...mapping,id:'network-map-'+i,identity_id:'network-identity-'+i,case_version_id:v.id,mapping:v.payload.compounds.map(c=>({source:c.id,target:c.id}))});d.reviews.push({...review,id:'network-review-'+i,case_version_id:v.id});});return d;}
